// Meta WhatsApp Cloud API payload -> clean structure
const raw = $input.first().json;
const body = raw.body || raw;
const value = body?.entry?.[0]?.changes?.[0]?.value;
const msg = value?.messages?.[0];

// Delivery/read status callbacks have no "messages" -> stop quietly
if (!msg) return [];

const contact = value?.contacts?.find(c => c.wa_id === msg.from) || value?.contacts?.[0];

let text = '';
if (msg.type === 'text') text = msg.text?.body || '';
else if (msg.type === 'button') text = msg.button?.text || '';
else if (msg.type === 'interactive') text = msg.interactive?.button_reply?.title || msg.interactive?.list_reply?.title || '';
else text = `[${msg.type} message received]`;

return [{
  json: {
    customer_name: (contact?.profile?.name || '').trim(),
    phone: String(msg.from || '').replace(/\D/g, ''),
    message: text.trim(),
    message_id: msg.id || '',
    timestamp: new Date(Number(msg.timestamp) * 1000).toISOString()
  }
}];

// Lead score (rule-based) + clean record for the rest of the flow
const n = $('Normalize WhatsApp Data').first().json;
const customer = $('Create Customer').isExecuted ? $('Create Customer').first().json : $('Check Customer').first().json;

let ai;
try { ai = JSON.parse($('AI Sales Agent').first().json.output); }
catch (e) { ai = { intent: 'general_question', product_interest: '', buying_stage: 'awareness', is_interested: false, needs_human: true, reply: '' }; }

let reply = String(ai.reply || '').trim().slice(0, 1000);
if (!reply) reply = 'Thanks for your message! A member of our team will get back to you shortly.';

const msg = (n.message || '').toLowerCase();
let score = 0;
if (ai.intent === 'pricing') score += 20;
if (ai.product_interest) score += 10;
if (ai.is_interested) score += 10;
if (ai.intent === 'purchase_intent') score += 35;
if (ai.intent === 'availability') score += 10;
if (/\b(demo|trial|walkthrough)\b/.test(msg)) score += 25;
if (/\b(call|meeting|schedule|talk to|speak to|callback)\b/.test(msg)) score += 20;
if (ai.buying_stage === 'consideration') score += 10;
if (ai.buying_stage === 'decision') score += 20;
score += Math.round((Number(customer.lead_score) || 0) * 0.5);   // carry over earlier engagement
score = Math.min(100, score);
const lead_temperature = score >= 70 ? 'Hot' : score >= 40 ? 'Warm' : 'Cold';

return [{ json: {
  customer_id: customer.id, customer_name: n.customer_name, phone: n.phone,
  message: n.message, message_id: n.message_id, timestamp: n.timestamp,
  intent: ai.intent || 'general_question', product_interest: ai.product_interest || '',
  buying_stage: ai.buying_stage || 'awareness', is_interested: !!ai.is_interested, needs_human: ai.needs_human === true,
  ai_response: reply, lead_score: score, lead_temperature
} }];

